INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000046-002', 'TKT-2026-000046', 2, 1, 'SYSTEM', NULL, 'SYSTEM_NOTE', 'MSG-TKT-2026-000046-001', '2026-01-08T10:08:38Z', 'hi', 'TPL-SYSTEM-EMAIL_ACK-hi', 'YottaFlex सहायता से संपर्क करने के लिए धन्यवाद। आपका टिकट प्राप्त हो गया है और हमारी टीम जल्द ही जवाब देगी।');
INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000046-003', 'TKT-2026-000046', 3, 1, 'AGENT', 'AGT-000021', 'EMAIL', 'MSG-TKT-2026-000046-001', '2026-01-08T10:27:45Z', 'hi', 'TPL-INT-004-AGENT-hi', 'हमने त्रुटि उत्पन्न करने वाले कॉन्फ़िगरेशन की पहचान कर ली है और समाधान लागू किया है। कृपया पुनः प्रयास करें।');
