INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000115-004', 'TKT-2026-000115', 4, 1, 'AGENT', 'AGT-000008', 'CHAT', 'MSG-TKT-2026-000115-003', '2026-01-13T17:00:32Z', 'ar', 'TPL-FOLLOWUP-AGENT-ar', 'شكرا لتقديم التفاصيل. لقد قمت بتطبيق التحديثات وكل شيء يعمل بشكل صحيح الآن.');
INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000116-001', 'TKT-2026-000116', 1, 1, 'CUSTOMER', NULL, 'CHAT', NULL, '2026-01-13T16:56:55Z', 'hi', 'TPL-INT-001-CUSTOMER-hi', 'नमस्ते, मेरे चालान पर हाल के शुल्कों के संबंध में मेरा एक प्रश्न है। क्या आप विवरण स्पष्ट कर सकते हैं?');
INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000116-002', 'TKT-2026-000116', 2, 1, 'AGENT', 'AGT-000029', 'CHAT', 'MSG-TKT-2026-000116-001', '2026-01-13T16:58:22Z', 'hi', 'TPL-INT-001-AGENT-hi', 'सहायता से संपर्क करने के लिए धन्यवाद। मैंने आपके खाते की जांच की है और बिलिंग विवरण सत्यापित किया है। शुल्क आपके प्लान का हिस्सा हैं।');
INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000116-003', 'TKT-2026-000116', 3, 1, 'CUSTOMER', NULL, 'CHAT', 'MSG-TKT-2026-000116-002', '2026-01-13T17:09:27Z', 'hi', 'TPL-FOLLOWUP-CUSTOMER-hi', 'अपडेट के लिए धन्यवाद। यहाँ अतिरिक्त जानकारी है जिसका आपने अनुरोध किया था।');
INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000116-004', 'TKT-2026-000116', 4, 1, 'AGENT', 'AGT-000029', 'CHAT', 'MSG-TKT-2026-000116-003', '2026-01-13T17:20:32Z', 'hi', 'TPL-FOLLOWUP-AGENT-hi', 'विवरण प्रदान करने के लिए धन्यवाद। मैंने अपडेट लागू कर दिए हैं और सब कुछ सही चल रहा है।');
