INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000295-001', 'TKT-2026-000295', 1, 1, 'CUSTOMER', NULL, 'CHAT', NULL, '2026-01-29T14:28:15Z', 'hi', 'TPL-INT-002-CUSTOMER-hi', 'नमस्ते, मैं अपने हालिया लेनदेन के लिए रिफंड का अनुरोध करना चाहता हूं क्योंकि सेवा उम्मीद के मुताबिक नहीं थी।');
INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000295-002', 'TKT-2026-000295', 2, 1, 'AGENT', 'AGT-000029', 'CHAT', 'MSG-TKT-2026-000295-001', '2026-01-29T14:31:33Z', 'hi', 'TPL-INT-002-AGENT-hi', 'मैं आपकी चिंता समझता हूँ और मैंने हमारी रिफंड नीति के अनुसार आपकी रिफंड प्रक्रिया शुरू कर दी है।');
