INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000338-001', 'TKT-2026-000338', 1, 1, 'CUSTOMER', NULL, 'EMAIL', NULL, '2026-01-29T19:59:24Z', 'hi', 'TPL-INT-001-CUSTOMER-hi', 'नमस्ते, मेरे चालान पर हाल के शुल्कों के संबंध में मेरा एक प्रश्न है। क्या आप विवरण स्पष्ट कर सकते हैं?');
INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000338-002', 'TKT-2026-000338', 2, 1, 'SYSTEM', NULL, 'SYSTEM_NOTE', 'MSG-TKT-2026-000338-001', '2026-01-29T19:59:39Z', 'hi', 'TPL-SYSTEM-EMAIL_ACK-hi', 'YottaFlex सहायता से संपर्क करने के लिए धन्यवाद। आपका टिकट प्राप्त हो गया है और हमारी टीम जल्द ही जवाब देगी।');
INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000338-003', 'TKT-2026-000338', 3, 1, 'AGENT', 'AGT-000007', 'EMAIL', 'MSG-TKT-2026-000338-001', '2026-01-29T20:04:43Z', 'hi', 'TPL-INT-001-AGENT-hi', 'सहायता से संपर्क करने के लिए धन्यवाद। मैंने आपके खाते की जांच की है और बिलिंग विवरण सत्यापित किया है। शुल्क आपके प्लान का हिस्सा हैं।');
INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000338-004', 'TKT-2026-000338', 4, 1, 'CUSTOMER', NULL, 'EMAIL', 'MSG-TKT-2026-000338-003', '2026-01-29T21:34:07Z', 'hi', 'TPL-FOLLOWUP-CUSTOMER-hi', 'अपडेट के लिए धन्यवाद। यहाँ अतिरिक्त जानकारी है जिसका आपने अनुरोध किया था।');
