INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000409-001', 'TKT-2026-000409', 1, 1, 'CUSTOMER', NULL, 'CHAT', NULL, '2026-02-06T13:24:18Z', 'hi', 'TPL-INT-001-CUSTOMER-hi', 'नमस्ते, मेरे चालान पर हाल के शुल्कों के संबंध में मेरा एक प्रश्न है। क्या आप विवरण स्पष्ट कर सकते हैं?');
