INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000491-001', 'TKT-2026-000491', 1, 1, 'CUSTOMER', NULL, 'EMAIL', NULL, '2026-02-16T10:59:45Z', 'hi', 'TPL-INT-005-CUSTOMER-hi', 'हमारी टीम प्लेटफ़ॉर्म से कनेक्ट नहीं हो पा रही है। क्या कोई सक्रिय सेवा रुकावट है?');
