INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000519-001', 'TKT-2026-000519', 1, 1, 'CUSTOMER', NULL, 'CHAT', NULL, '2026-02-18T18:23:11Z', 'hi', 'TPL-INT-002-CUSTOMER-hi', 'नमस्ते, मैं अपने हालिया लेनदेन के लिए रिफंड का अनुरोध करना चाहता हूं क्योंकि सेवा उम्मीद के मुताबिक नहीं थी।');
