INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000671-002', 'TKT-2026-000671', 2, 1, 'SYSTEM', NULL, 'SYSTEM_NOTE', 'MSG-TKT-2026-000671-001', '2026-03-04T15:33:54Z', 'hi', 'TPL-SYSTEM-EMAIL_ACK-hi', 'YottaFlex सहायता से संपर्क करने के लिए धन्यवाद। आपका टिकट प्राप्त हो गया है और हमारी टीम जल्द ही जवाब देगी।');
