INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000728-001', 'TKT-2026-000728', 1, 1, 'CUSTOMER', NULL, 'EMAIL', NULL, '2026-03-09T18:34:03Z', 'hi', 'TPL-INT-004-CUSTOMER-hi', 'डैशबोर्ड तक पहुंचने का प्रयास करते समय मुझे एक त्रुटि संदेश मिल रहा है। कृपया सहायता करें।');
INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000728-002', 'TKT-2026-000728', 2, 1, 'SYSTEM', NULL, 'SYSTEM_NOTE', 'MSG-TKT-2026-000728-001', '2026-03-09T18:34:18Z', 'hi', 'TPL-SYSTEM-EMAIL_ACK-hi', 'YottaFlex सहायता से संपर्क करने के लिए धन्यवाद। आपका टिकट प्राप्त हो गया है और हमारी टीम जल्द ही जवाब देगी।');
