INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000924-001', 'TKT-2026-000924', 1, 1, 'CUSTOMER', NULL, 'EMAIL', NULL, '2026-03-27T18:40:28Z', 'hi', 'TPL-INT-007-CUSTOMER-hi', 'कृपया हमारी कंपनी के खाते से जुड़े प्राथमिक संपर्क ईमेल और बिलिंग पते को अपडेट करें।');
INSERT INTO message (message_id, ticket_id, seq_no, cycle_no, sender_type, sender_agent_id, message_type, in_reply_to_message_id, sent_at, language_code, template_id, body) VALUES ('MSG-TKT-2026-000924-002', 'TKT-2026-000924', 2, 1, 'SYSTEM', NULL, 'SYSTEM_NOTE', 'MSG-TKT-2026-000924-001', '2026-03-27T18:40:43Z', 'hi', 'TPL-SYSTEM-EMAIL_ACK-hi', 'YottaFlex सहायता से संपर्क करने के लिए धन्यवाद। आपका टिकट प्राप्त हो गया है और हमारी टीम जल्द ही जवाब देगी।');
